CREATE TABLE IF NOT EXISTS pharma_evidence_cases(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,compound_id TEXT NOT NULL,subject_id TEXT NOT NULL,intended_use TEXT NOT NULL,payload JSONB NOT NULL,evidence_summary JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'evidence_draft' CHECK(status IN('evidence_draft','rules_checked','review_pending','professionally_approved','rejected')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,approved_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS pharma_evidence_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_id BIGINT NOT NULL REFERENCES pharma_evidence_cases(id),actor_id TEXT NOT NULL,event_type TEXT NOT NULL,from_status TEXT,to_status TEXT,event_data JSONB NOT NULL DEFAULT '{}'::jsonb,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION reject_pharma_event_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'pharmaceutical evidence history is append-only';END$$;DROP TRIGGER IF EXISTS pharma_evidence_events_immutable ON pharma_evidence_events;CREATE TRIGGER pharma_evidence_events_immutable BEFORE UPDATE OR DELETE ON pharma_evidence_events FOR EACH ROW EXECUTE FUNCTION reject_pharma_event_mutation();CREATE INDEX IF NOT EXISTS pharma_evidence_tenant_status_idx ON pharma_evidence_cases(tenant_id,status,updated_at DESC);

